from typing import List

def process_times(n: int, a: int, T: List[int]) -> List[int]:
    current_time = 0
    finish_times = []
    for t in T:
        if t >= current_time:
            current_time = t + a
        else:
            current_time += a
        finish_times.append(current_time)
    return finish_times
